// Flush streamed rows in bounded batches so very large fetches still surface
// progressive UI updates without waiting for oversized buffers.
// Send buffered rows when either:
// - first batch reaches 10,000 rows
// - 200ms passes
// - an additional batch reaches 10,000 rows
pub(super) const PROGRESS_ROWS_INITIAL_BATCH: usize = 10_000;
const PROGRESS_ROWS_FLUSH_INTERVAL: Duration = Duration::from_millis(200);
const PROGRESS_ROWS_MAX_BATCH: usize = 10_000;
const ORACLE_THIN_FETCH_ALL_MIN_BATCH: usize = 5_000;
const ORACLE_THIN_LAZY_CLEANUP_FALLBACK_TIMEOUT: Duration = Duration::from_secs(5);
const MAX_SCRIPT_INCLUDE_DEPTH: usize = 64;
const SESSION_POOL_CANCEL_WAIT_TIMEOUT: Duration = Duration::from_secs(2);
const SESSION_POOL_CANCEL_RESPONSE_TIMEOUT: Duration = Duration::from_millis(750);
const SESSION_POOL_CANCEL_RETRY_INTERVAL: Duration = Duration::from_millis(100);
const LAZY_FETCH_CANCEL_RETRY_DELAY_SECONDS: f64 = 0.2;
const LAZY_FETCH_CANCEL_RETRY_LIMIT: u32 = 50;
const ORACLE_THIN_HEALTH_CHECK_SQL: &str = "SELECT '1' FROM dual";
const ORACLE_RETAINED_SESSION_LOST_AFTER_SUCCESS_MESSAGE: &str =
    "The Oracle statement succeeded, but its transaction or session state could not be retained. The physical session was discarded.";
const ORACLE_SCOPE_SYNC_LOST_AFTER_SUCCESS_MESSAGE: &str =
    "The Oracle statement succeeded and changed the current schema, but the global current schema could not be synchronized.";
const MYSQL_RETAINED_SESSION_LOST_AFTER_SUCCESS_MESSAGE: &str =
    "The MySQL statement succeeded, but its transaction or session state could not be retained. The physical session was discarded.";
const MYSQL_SCOPE_SYNC_LOST_AFTER_SUCCESS_MESSAGE: &str =
    "The MySQL statement succeeded and changed the current database, but the global database selection could not be synchronized.";

