    #[test]
    fn oracle_manual_transaction_control_hints_preserve_state() {
        for sql in [
            "SAVEPOINT sp1",
            "ROLLBACK TO SAVEPOINT sp1",
            "SET TRANSACTION READ ONLY",
            "LOCK TABLE t IN EXCLUSIVE MODE",
        ] {
            let effects =
                crate::db::statement_session_post_processor_for(crate::db::DatabaseType::Oracle)
                    .effects_for_sql(sql);
            assert!(
                effects.opens_or_preserves_transaction_state(),
                "{sql} should preserve an Oracle transaction/session state"
            );
            assert!(
                effects.skip_auto_commit(),
                "{sql} must not be followed by client auto-commit"
            );
        }

        let create_table_effects =
            crate::db::statement_session_post_processor_for(crate::db::DatabaseType::Oracle)
                .effects_for_sql("CREATE TABLE t (id NUMBER)");
        assert!(create_table_effects.has_implicit_commit());

        for sql in [
            "COMMIT WORK",
            "COMMIT COMMENT 'done'",
            "COMMIT WRITE WAIT",
            "ROLLBACK WORK",
        ] {
            let effects =
                crate::db::statement_session_post_processor_for(crate::db::DatabaseType::Oracle)
                    .effects_for_sql(sql);
            assert!(
                effects.clears_transaction_state(),
                "{sql} should clear the pooled Oracle transaction state"
            );
            assert!(
                effects.skip_auto_commit(),
                "{sql} must not be followed by client auto-commit"
            );
        }

        let alter_session_effects =
            crate::db::statement_session_post_processor_for(crate::db::DatabaseType::Oracle)
                .effects_for_sql("ALTER SESSION SET ISOLATION_LEVEL = SERIALIZABLE");
        assert!(!alter_session_effects.has_implicit_commit());
        assert!(alter_session_effects.skip_auto_commit());

        assert!(
            crate::db::statement_session_post_processor_for(crate::db::DatabaseType::Oracle)
                .effects_for_sql("COMMIT FORCE '1.2.3'")
                .requires_transaction_decision_after_success()
        );
        assert!(
            crate::db::statement_session_post_processor_for(crate::db::DatabaseType::Oracle)
                .effects_for_sql("ROLLBACK FORCE '1.2.3'")
                .requires_transaction_decision_after_success()
        );
        assert!(
            !crate::db::statement_session_post_processor_for(crate::db::DatabaseType::Oracle)
                .effects_for_sql("COMMIT COMMENT 'done'")
                .requires_transaction_decision_after_success()
        );
        assert!(
            !crate::db::statement_session_post_processor_for(crate::db::DatabaseType::Oracle)
                .effects_for_sql("COMMIT WRITE WAIT")
                .requires_transaction_decision_after_success()
        );
        assert!(
            !crate::db::statement_session_post_processor_for(crate::db::DatabaseType::Oracle)
                .effects_for_sql("ROLLBACK TO SAVEPOINT sp1")
                .requires_transaction_decision_after_success()
        );
    }

    #[test]
    fn oracle_cleanup_records_manual_transaction_delta_as_dirty() {
        let post_processor =
            crate::db::statement_session_post_processor_for(crate::db::DatabaseType::Oracle);

        for sql in [
            "SAVEPOINT sp1",
            "SET TRANSACTION READ ONLY",
            "LOCK TABLE t IN EXCLUSIVE MODE",
        ] {
            let (sender, _receiver) = mpsc::channel();
            let mut cleanup = new_test_cleanup_guard(
                sender,
                Arc::new(Mutex::new(None)),
                Arc::new(Mutex::new(None)),
                Arc::new(Mutex::new(false)),
                Arc::new(Mutex::new(true)),
            );

            SqlEditorWidget::apply_oracle_db_statement_effects(
                &mut cleanup,
                post_processor.effects_for_sql(sql),
            );

            assert_eq!(
                cleanup
                    .oracle_pooled_session_state_delta
                    .transaction_state(),
                TransactionSessionState::MaybeDirty,
                "{sql} must not be recorded as a clean Oracle transaction delta",
            );
            assert_eq!(
                cleanup
                    .oracle_retained_state_for_connection_transition(false)
                    .transaction_state(),
                TransactionSessionState::MaybeDirty,
                "{sql} must still require transaction resolution even when row-change probes are clean",
            );
        }
    }

