    #[test]
    fn oracle_successful_statement_clears_late_cancel_protection() {
        for auto_commit in [true, false] {
            let (sender, _receiver) = mpsc::channel();
            let mut cleanup = new_test_cleanup_guard(
                sender,
                Arc::new(Mutex::new(None)),
                Arc::new(Mutex::new(None)),
                Arc::new(Mutex::new(true)),
                Arc::new(Mutex::new(true)),
            );
            cleanup.protect_oracle_dirty_statement_on_cancel(auto_commit);

            assert_eq!(
                cleanup.oracle_pooled_session_invalidated_on_cancel,
                auto_commit
            );
            assert_eq!(
                cleanup.oracle_pooled_session_transaction_decision_on_cancel,
                !auto_commit
            );

            cleanup.clear_oracle_successful_statement_cancel_protection();

            assert!(
                !cleanup.oracle_pooled_session_invalidated_on_cancel,
                "successful auto-commit statement should not discard on a late cancel"
            );
            assert!(
                !cleanup.oracle_pooled_session_transaction_decision_on_cancel,
                "successful manual-commit statement should not require a decision only because cancel was clicked late"
            );
        }
    }

    #[test]
    fn oracle_late_cancel_without_session_effect_does_not_drive_cleanup_policy() {
        let (sender, _receiver) = mpsc::channel();
        let mut cleanup = new_test_cleanup_guard(
            sender,
            Arc::new(Mutex::new(None)),
            Arc::new(Mutex::new(None)),
            Arc::new(Mutex::new(true)),
            Arc::new(Mutex::new(true)),
        );

        assert!(
            !cleanup.oracle_cancel_affects_session_policy(true),
            "a cancel clicked after a successful statement should stop the script loop, not force a session interrupt decision"
        );

        cleanup.protect_oracle_dirty_statement_on_cancel(false);
        assert!(
            cleanup.oracle_cancel_affects_session_policy(true),
            "cancel-contingent transaction protection should still affect cleanup while armed"
        );

        cleanup.clear_oracle_successful_statement_cancel_protection();
        assert!(!cleanup.oracle_cancel_affects_session_policy(true));

        cleanup.execution_metadata.cancelled = true;
        assert!(
            cleanup.oracle_cancel_affects_session_policy(false),
            "a driver-confirmed cancel must affect cleanup even if the UI flag has already been cleared"
        );
    }

