    #[test]
    fn oracle_successful_select_for_update_auto_commit_clears_dirty_state() {
        let (sender, _receiver) = mpsc::channel();
        let mut cleanup = new_test_cleanup_guard(
            sender,
            Arc::new(Mutex::new(None)),
            Arc::new(Mutex::new(None)),
            Arc::new(Mutex::new(false)),
            Arc::new(Mutex::new(true)),
        );
        let effects =
            crate::db::statement_session_post_processor_for(crate::db::DatabaseType::Oracle)
                .effects_for_sql("SELECT * FROM accounts FOR UPDATE");
        let mut commit_calls = 0;

        let auto_committed = SqlEditorWidget::apply_successful_oracle_select_statement_effects(
            &mut cleanup,
            effects,
            true,
            || {
                commit_calls += 1;
                Ok(())
            },
        )
        .expect("successful auto-commit should not fail");

        assert!(auto_committed);
        assert_eq!(commit_calls, 1);
        assert!(!cleanup.oracle_pooled_session_forced_maybe_dirty);
        assert!(!cleanup.oracle_pooled_session_transaction_decision_required);
    }

