    #[test]
    fn connection_transition_requires_resolution_for_dirty_or_decision_sessions() {
        let clean_snapshot = crate::db::PooledSessionLeaseSnapshot {
            db_type: crate::db::DatabaseType::MySQL,
            pool_context_epoch: 0,
            transaction_state: TransactionSessionState::Clean,
            retained_state: RetainedSessionState::from_transaction_state(
                TransactionSessionState::Clean,
            ),
        };
        let dirty_snapshot = crate::db::PooledSessionLeaseSnapshot {
            db_type: crate::db::DatabaseType::MySQL,
            pool_context_epoch: 0,
            transaction_state: TransactionSessionState::MaybeDirty,
            retained_state: RetainedSessionState::from_transaction_state(
                TransactionSessionState::MaybeDirty,
            ),
        };
        let decision_snapshot = crate::db::PooledSessionLeaseSnapshot {
            db_type: crate::db::DatabaseType::Oracle,
            pool_context_epoch: 0,
            transaction_state: TransactionSessionState::DecisionRequired,
            retained_state: RetainedSessionState::from_transaction_state(
                TransactionSessionState::DecisionRequired,
            ),
        };
        let post_processor =
            crate::db::statement_session_post_processor_for(crate::db::DatabaseType::MySQL);
        let transaction_mode_override_state = crate::db::retained_session_state_after_statement(
            post_processor,
            RetainedSessionState::default(),
            post_processor.effects_for_sql("SET TRANSACTION ISOLATION LEVEL SERIALIZABLE"),
            false,
            false,
            false,
            false,
        );
        let transaction_mode_snapshot = crate::db::PooledSessionLeaseSnapshot {
            db_type: crate::db::DatabaseType::MySQL,
            pool_context_epoch: 0,
            transaction_state: TransactionSessionState::Clean,
            retained_state: transaction_mode_override_state,
        };

        assert!(
            !SqlEditorWidget::connection_transition_requires_transaction_resolution(false, None)
        );
        assert!(
            !SqlEditorWidget::connection_transition_requires_transaction_resolution(
                false,
                Some(clean_snapshot)
            )
        );
        assert!(
            SqlEditorWidget::connection_transition_requires_transaction_resolution(
                true,
                Some(clean_snapshot)
            )
        );
        assert!(
            SqlEditorWidget::connection_transition_requires_transaction_resolution(
                false,
                Some(dirty_snapshot)
            )
        );
        assert!(
            SqlEditorWidget::connection_transition_requires_transaction_resolution(
                false,
                Some(decision_snapshot)
            )
        );
        assert!(
            SqlEditorWidget::connection_transition_requires_transaction_resolution(
                false,
                Some(transaction_mode_snapshot)
            )
        );
    }

    #[test]
    fn mysql_raw_autocommit_statement_updates_state_only_after_success() {
        let success = QueryResult {
            sql: "SET SESSION autocommit = 0".to_string(),
            columns: vec![],
            rows: vec![],
            row_count: 0,
            execution_time: Duration::from_secs(0),
            message: "OK".to_string(),
            is_select: false,
            success: true,
        };
        let failure = QueryResult {
            success: false,
            message: "Error".to_string(),
            ..success.clone()
        };

        assert_eq!(
            SqlEditorWidget::mysql_autocommit_change_after_successful_statement(
                "SET SESSION autocommit = 0",
                std::slice::from_ref(&success),
            ),
            Some(false)
        );
        assert_eq!(
            SqlEditorWidget::mysql_autocommit_change_after_successful_statement(
                "SET autocommit = ON",
                std::slice::from_ref(&success),
            ),
            Some(true)
        );
        assert_eq!(
            SqlEditorWidget::mysql_autocommit_change_after_successful_statement(
                "SET @@session.autocommit = OFF",
                std::slice::from_ref(&success),
            ),
            Some(false)
        );
        assert_eq!(
            SqlEditorWidget::mysql_autocommit_change_after_successful_statement(
                "SET @@autocommit = TRUE, sql_notes = 0",
                std::slice::from_ref(&success),
            ),
            Some(true)
        );
        assert_eq!(
            SqlEditorWidget::mysql_autocommit_change_after_successful_statement(
                "SET sql_notes = 0, autocommit = 0",
                std::slice::from_ref(&success),
            ),
            Some(false)
        );
        assert_eq!(
            SqlEditorWidget::mysql_autocommit_change_after_successful_statement(
                "SET autocommit = 0, sql_notes = 0, autocommit = 1",
                std::slice::from_ref(&success),
            ),
            Some(true)
        );
        assert_eq!(
            SqlEditorWidget::mysql_autocommit_change_after_successful_statement(
                "SET GLOBAL autocommit = 0",
                std::slice::from_ref(&success),
            ),
            None
        );
        assert_eq!(
            SqlEditorWidget::mysql_autocommit_change_after_successful_statement(
                "SET LOCAL autocommit = 0",
                std::slice::from_ref(&success),
            ),
            Some(false)
        );
        assert_eq!(
            SqlEditorWidget::mysql_autocommit_change_after_successful_statement(
                "SET LOCAL autocommit = 1",
                std::slice::from_ref(&success),
            ),
            Some(true)
        );
        // session-scope `@@LOCAL.AUTOCOMMIT` must propagate to the override
        // exactly like `SET LOCAL autocommit` and `SET @@SESSION.AUTOCOMMIT`.
        assert_eq!(
            SqlEditorWidget::mysql_autocommit_change_after_successful_statement(
                "SET @@local.autocommit = 0",
                std::slice::from_ref(&success),
            ),
            Some(false),
        );
        assert_eq!(
            SqlEditorWidget::mysql_autocommit_change_after_successful_statement(
                "SET @@LOCAL.AUTOCOMMIT = ON",
                std::slice::from_ref(&success),
            ),
            Some(true),
        );
        assert_eq!(
            SqlEditorWidget::mysql_autocommit_change_after_successful_statement(
                "SET autocommit = 'OFF'",
                std::slice::from_ref(&success),
            ),
            Some(false),
        );
        assert_eq!(
            SqlEditorWidget::mysql_autocommit_change_after_successful_statement(
                "SET @@session.autocommit = (\"ON\")",
                std::slice::from_ref(&success),
            ),
            Some(true),
        );
        assert_eq!(
            SqlEditorWidget::mysql_autocommit_change_after_successful_statement_for_db_type(
                crate::db::DatabaseType::MariaDB,
                "SET STATEMENT max_statement_time=1 FOR SET autocommit = OFF",
                std::slice::from_ref(&success),
            ),
            Some(false),
            "MariaDB SET STATEMENT wrappers must propagate inner autocommit changes",
        );
        assert_eq!(
            SqlEditorWidget::mysql_autocommit_change_after_successful_statement(
                "SET autocommit = 1",
                &[failure],
            ),
            None
        );
    }

    #[test]
    fn cleanup_guard_resets_cancel_and_emits_batch_finished_on_drop() {
        let (sender, receiver) = mpsc::channel();
        let cancel_flag = Arc::new(Mutex::new(true));
        let query_running = Arc::new(Mutex::new(true));
        let current_query_connection: Arc<Mutex<Option<Arc<Connection>>>> =
            Arc::new(Mutex::new(None));
        let current_mysql_cancel_context: Arc<Mutex<Option<MySqlQueryCancelContext>>> =
            Arc::new(Mutex::new(None));

        {
            let _guard = new_test_cleanup_guard(
                sender,
                current_query_connection.clone(),
                current_mysql_cancel_context.clone(),
                cancel_flag.clone(),
                query_running.clone(),
            );
        }

        assert!(!cancel_flag
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .to_owned());
        assert!(!query_running
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .to_owned());
        let events = receiver.try_iter().collect::<Vec<_>>();
        assert!(
            events
                .iter()
                .any(|msg| matches!(msg, QueryProgress::BatchFinished)),
            "BatchFinished should be emitted"
        );
        assert!(
            events.iter().any(|msg| matches!(
                msg,
                QueryProgress::ExecutionFinished(event)
                    if event.cancelled && event.timeout_settings_restored
            )),
            "ExecutionFinished should carry cancel cleanup metadata"
        );
        assert!(current_query_connection
            .lock()
            .expect("connection mutex should not be poisoned")
            .is_none());
        assert!(current_mysql_cancel_context
            .lock()
            .expect("MySQL cancel context mutex should not be poisoned")
            .is_none());
    }

    #[test]
    fn cleanup_guard_does_not_clear_newer_operation_after_abandon() {
        let (sender, receiver) = mpsc::channel();
        let cancel_flag = Arc::new(Mutex::new(true));
        let query_running = Arc::new(Mutex::new(true));
        let current_query_cancel_handle = Arc::new(Mutex::new(Some(QueryCancelHandle::Test(
            Arc::new(AtomicBool::new(false)),
        ))));
        let current_operation_id = Arc::new(AtomicU64::new(43));
        let last_completed_operation_id = Arc::new(AtomicU64::new(0));

        {
            let mut guard = QueryExecutionCleanupGuard::new(
                crate::db::DatabaseType::MySQL,
                sender,
                Arc::new(Mutex::new(None)),
                Arc::new(Mutex::new(None)),
                current_query_cancel_handle.clone(),
                Arc::new(Mutex::new(None::<MySqlQueryCancelContext>)),
                cancel_flag.clone(),
                query_running.clone(),
                Arc::new(AtomicU64::new(7)),
                0,
                current_operation_id.clone(),
                last_completed_operation_id.clone(),
                Arc::new(Mutex::new(crate::db::session_policy::SqlKind::SelectLike)),
                Arc::new(Mutex::new(true)),
            );
            guard.track_execution_metadata(
                crate::db::DatabaseType::MySQL,
                crate::db::session_policy::SqlKind::SelectLike,
                42,
                11,
            );
        }

        assert!(*cancel_flag.lock().unwrap());
        assert!(*query_running.lock().unwrap());
        assert_eq!(current_operation_id.load(Ordering::Relaxed), 43);
        assert_eq!(last_completed_operation_id.load(Ordering::Relaxed), 0);
        assert!(current_query_cancel_handle.lock().unwrap().is_some());
        assert!(
            receiver
                .try_iter()
                .any(|msg| matches!(msg, QueryProgress::BatchFinished)),
            "stale cleanup may still notify completion, but must not clear newer editor state"
        );
    }

    #[test]
    fn mysql_cleanup_guard_marks_cancel_without_timeout_as_restored() {
        let (sender, receiver) = mpsc::channel();
        let cancel_flag = Arc::new(Mutex::new(true));
        let query_running = Arc::new(Mutex::new(true));
        let current_operation_id = Arc::new(AtomicU64::new(42));
        let last_completed_operation_id = Arc::new(AtomicU64::new(0));

        {
            let mut guard = QueryExecutionCleanupGuard::new(
                crate::db::DatabaseType::MySQL,
                sender,
                Arc::new(Mutex::new(None)),
                Arc::new(Mutex::new(None)),
                Arc::new(Mutex::new(None::<QueryCancelHandle>)),
                Arc::new(Mutex::new(None)),
                cancel_flag,
                query_running,
                Arc::new(AtomicU64::new(7)),
                0,
                current_operation_id,
                last_completed_operation_id.clone(),
                Arc::new(Mutex::new(crate::db::session_policy::SqlKind::SelectLike)),
                Arc::new(Mutex::new(true)),
            );
            guard.track_execution_metadata(
                crate::db::DatabaseType::MySQL,
                crate::db::session_policy::SqlKind::SelectLike,
                42,
                11,
            );
        }

        let events = receiver.try_iter().collect::<Vec<_>>();
        assert!(
            events.iter().any(|msg| matches!(
                msg,
                QueryProgress::ExecutionFinished(event)
                    if event.db_type == crate::db::DatabaseType::MySQL
                        && event.cancelled
                        && event.timeout_settings_restored
            )),
            "a MySQL cancel with no timeout restore object should be eligible for reuse policy"
        );
        assert_eq!(
            last_completed_operation_id.load(Ordering::Relaxed),
            42,
            "cleanup must preserve the completed operation id for UI stale-event gating"
        );
    }

    #[test]
