    #[test]
    fn cleanup_guard_runs_during_panic_unwind() {
        let (sender, receiver) = mpsc::channel();
        let cancel_flag = Arc::new(Mutex::new(true));
        let query_running = Arc::new(Mutex::new(true));
        let current_query_connection: Arc<Mutex<Option<Arc<Connection>>>> =
            Arc::new(Mutex::new(None));
        let current_mysql_cancel_context: Arc<Mutex<Option<MySqlQueryCancelContext>>> =
            Arc::new(Mutex::new(None));

        let unwind_result = panic::catch_unwind(AssertUnwindSafe({
            let cancel_flag = cancel_flag.clone();
            let current_query_connection = current_query_connection;
            let current_mysql_cancel_context = current_mysql_cancel_context;
            let query_running = query_running.clone();
            move || {
                let _guard = new_test_cleanup_guard(
                    sender,
                    current_query_connection,
                    current_mysql_cancel_context,
                    cancel_flag,
                    query_running,
                );
                panic!("simulate execution panic");
            }
        }));

        assert!(unwind_result.is_err());
        assert!(!cancel_flag
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .to_owned());
        assert!(!query_running
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .to_owned());
        let events = receiver.try_iter().collect::<Vec<_>>();
        assert!(
            events
                .iter()
                .any(|msg| matches!(msg, QueryProgress::BatchFinished)),
            "BatchFinished should be emitted"
        );
    }

    fn oracle_test_connection() -> Option<(DatabaseConnection, Arc<Connection>)> {
        let Some(username) = env::var("ORACLE_TEST_USERNAME")
            .ok()
            .filter(|value| !value.trim().is_empty())
        else {
            eprintln!("skipping: ORACLE_TEST_USERNAME is not set");
            return None;
        };
        let Some(password) = env::var("ORACLE_TEST_PASSWORD")
            .ok()
            .filter(|value| !value.trim().is_empty())
        else {
            eprintln!("skipping: ORACLE_TEST_PASSWORD is not set");
            return None;
        };
        let Some(service_name) = env::var("ORACLE_TEST_SERVICE_NAME")
            .ok()
            .filter(|value| !value.trim().is_empty())
        else {
            eprintln!("skipping: ORACLE_TEST_SERVICE_NAME is not set");
            return None;
        };
        let host = env::var("ORACLE_TEST_HOST").unwrap_or_else(|_| "localhost".to_string());
        let port = env::var("ORACLE_TEST_PORT")
            .ok()
            .and_then(|value| value.parse::<u16>().ok())
            .unwrap_or(1521);

        let mut connection = DatabaseConnection::new();
        connection
            .connect(ConnectionInfo::new_with_type(
                "ORACLE_TEST",
                &username,
                &password,
                &host,
                port,
                &service_name,
                DatabaseType::Oracle,
            ))
            .expect("Oracle test connection should succeed");
        let conn = connection
            .require_live_connection()
            .expect("Oracle test connection should be live");
        Some((connection, conn))
    }

