    #[test]
    #[ignore = "requires local Oracle database via ORACLE_TEST_* environment variables"]
    fn oracle_cleanup_replace_drops_checked_out_session_even_when_slot_is_empty() {
        let Some((connection, _main_conn)) = oracle_test_connection() else {
            return;
        };
        let Some(crate::db::DbPoolSession::Oracle(conn)) = connection
            .acquire_pool_session()
            .expect("Oracle pool session should be acquired")
        else {
            panic!("expected Oracle pool session");
        };
        let conn = Arc::new(conn);
        let pooled_db_session = crate::db::SharedDbSessionLease::new();
        {
            let (sender, _receiver) = mpsc::channel();
            let mut cleanup = new_test_cleanup_guard(
                sender,
                Arc::new(Mutex::new(None)),
                Arc::new(Mutex::new(None)),
                Arc::new(Mutex::new(false)),
                Arc::new(Mutex::new(true)),
            );
            cleanup.track_oracle_pooled_session(
                pooled_db_session,
                9,
                0,
                Arc::clone(&conn),
                RetainedSessionState::default(),
            );
            cleanup.invalidate_oracle_pooled_session();
        }

        assert_eq!(
            conn.status().expect("Oracle status probe should succeed"),
            ConnStatus::Closed,
            "replace/discard cleanup must close the checked-out Oracle session even though the retained-session slot is empty during execution"
        );
    }

    #[test]
    fn cleanup_guard_drop_tolerates_closed_progress_channel() {
        let (sender, receiver) = mpsc::channel();
        drop(receiver);

        let cancel_flag = Arc::new(Mutex::new(true));
        let query_running = Arc::new(Mutex::new(true));
        let current_query_connection: Arc<Mutex<Option<Arc<Connection>>>> =
            Arc::new(Mutex::new(None));
        let current_mysql_cancel_context: Arc<Mutex<Option<MySqlQueryCancelContext>>> =
            Arc::new(Mutex::new(None));

        let drop_result = panic::catch_unwind(AssertUnwindSafe(|| {
            let _guard = new_test_cleanup_guard(
                sender,
                current_query_connection,
                current_mysql_cancel_context,
                cancel_flag.clone(),
                query_running.clone(),
            );
        }));

        assert!(drop_result.is_ok(), "Drop must ignore send failures");
        assert!(!cancel_flag
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .to_owned());
        assert!(!query_running
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .to_owned());
    }

    #[test]
    fn cleanup_guard_recovers_from_poisoned_connection_mutex() {
        let (sender, receiver) = mpsc::channel();
        let cancel_flag = Arc::new(Mutex::new(true));
        let query_running = Arc::new(Mutex::new(true));
        let current_query_connection: Arc<Mutex<Option<Arc<Connection>>>> =
            Arc::new(Mutex::new(None));
        let current_mysql_cancel_context: Arc<Mutex<Option<MySqlQueryCancelContext>>> =
            Arc::new(Mutex::new(None));

        let poison_target = current_query_connection.clone();
        let _ = panic::catch_unwind(AssertUnwindSafe(move || {
            let _lock = poison_target
                .lock()
                .expect("mutex lock should succeed before poisoning");
            panic!("poison current_query_connection mutex");
        }));

        {
            let _guard = new_test_cleanup_guard(
                sender,
                current_query_connection,
                current_mysql_cancel_context,
                cancel_flag.clone(),
                query_running.clone(),
            );
        }

        assert!(!cancel_flag
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .to_owned());
        assert!(!query_running
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .to_owned());
        let events = receiver.try_iter().collect::<Vec<_>>();
        assert!(
            events
                .iter()
                .any(|msg| matches!(msg, QueryProgress::BatchFinished)),
            "BatchFinished should be emitted"
        );
    }

