    #[test]
    fn lazy_cancel_drain_preserves_non_cancel_commands() {
        let (sender, receiver) = mpsc::channel();
        sender
            .send(LazyFetchCommand::FetchMore(25))
            .expect("send fetch more");
        sender
            .send(LazyFetchCommand::FetchAll)
            .expect("send fetch all");
        let mut pending = std::collections::VecDeque::new();

        assert!(SqlEditorWidget::drain_lazy_cancel_request(&receiver, &mut pending).is_none());
        assert!(matches!(
            pending.pop_front(),
            Some(LazyFetchCommand::FetchMore(25))
        ));
        assert!(matches!(
            pending.pop_front(),
            Some(LazyFetchCommand::FetchAll)
        ));
        assert!(pending.is_empty());
    }

    #[test]
    fn lazy_cancel_drain_detects_cancel_after_queued_fetches() {
        let (sender, receiver) = mpsc::channel();
        sender
            .send(LazyFetchCommand::FetchMore(25))
            .expect("send fetch more");
        sender
            .send(LazyFetchCommand::CancelFetch)
            .expect("send cancel");
        let mut pending = std::collections::VecDeque::new();

        assert!(matches!(
            SqlEditorWidget::drain_lazy_cancel_request(&receiver, &mut pending),
            Some(LazyFetchCommand::CancelFetch)
        ));
        assert!(matches!(
            pending.pop_front(),
            Some(LazyFetchCommand::FetchMore(25))
        ));
        assert!(pending.is_empty());
    }

    #[test]
    fn lazy_cancel_preempts_pending_fetch_before_next_db_call() {
        let (sender, receiver) = mpsc::channel();
        sender
            .send(LazyFetchCommand::CancelFetch)
            .expect("send cancel");
        let mut pending = std::collections::VecDeque::from([LazyFetchCommand::FetchMore(25)]);

        assert!(matches!(
            SqlEditorWidget::next_lazy_fetch_command(&receiver, &mut pending),
            Ok(LazyFetchCommand::CancelFetch)
        ));
        assert!(matches!(
            pending.pop_front(),
            Some(LazyFetchCommand::FetchMore(25))
        ));
        assert!(pending.is_empty());
    }

    #[test]
    fn lazy_fetch_command_send_marks_queued_fetch_as_cancel_target() {
        let (sender, _receiver) = mpsc::channel();
        let handle = LazyFetchHandle {
            index: 0,
            session_id: 42,
            operation_id: 42,
            connection_generation: 7,
            sender,
            cancel_handle: None,
            cancel_requested: Arc::new(AtomicBool::new(false)),
            retain_session_on_cancel: Arc::new(AtomicBool::new(false)),
            db_cancel_requested: Arc::new(AtomicBool::new(false)),
            fetch_in_progress: Arc::new(AtomicBool::new(false)),
        };

        SqlEditorWidget::mark_lazy_fetch_command_send_start(
            &handle,
            &LazyFetchCommand::FetchMore(25),
        );
        assert!(
            handle.fetch_in_progress.load(Ordering::Relaxed),
            "queued FetchMore must be cancellable as an in-flight DB call"
        );

        SqlEditorWidget::mark_lazy_fetch_command_send_failed(
            &handle,
            &LazyFetchCommand::FetchMore(25),
        );
        assert!(
            !handle.fetch_in_progress.load(Ordering::Relaxed),
            "failed FetchMore send should restore waiting state"
        );

        SqlEditorWidget::mark_lazy_fetch_command_send_start(
            &handle,
            &LazyFetchCommand::GracefulClose,
        );
        assert!(
            !handle.fetch_in_progress.load(Ordering::Relaxed),
            "GracefulClose should not be treated as a DB fetch"
        );
    }

