    #[test]
    fn lazy_fetch_cancel_watchdog_forces_close_and_clears_handle() {
        let (command_sender, command_receiver) = mpsc::channel();
        let (progress_sender, progress_receiver) = mpsc::channel();
        let db_cancel_called = Arc::new(AtomicBool::new(false));
        let active = Arc::new(Mutex::new(Some(LazyFetchHandle {
            index: 3,
            session_id: 42,
            operation_id: 42,
            connection_generation: 7,
            sender: command_sender,
            cancel_handle: Some(LazyFetchCancelHandle::Test(db_cancel_called.clone())),
            cancel_requested: Arc::new(AtomicBool::new(true)),
            retain_session_on_cancel: Arc::new(AtomicBool::new(true)),
            db_cancel_requested: Arc::new(AtomicBool::new(true)),
            fetch_in_progress: Arc::new(AtomicBool::new(true)),
        })));

        SqlEditorWidget::start_lazy_fetch_cancel_watchdog_with(
            active.clone(),
            progress_sender,
            42,
            Duration::from_millis(1),
        );

        let event = progress_receiver
            .recv_timeout(Duration::from_secs(1))
            .expect("watchdog should emit lazy close");
        assert!(!SqlEditorWidget::lazy_fetch_handle_matches(&active, 42));
        assert!(matches!(
            command_receiver.recv_timeout(Duration::from_secs(1)),
            Ok(LazyFetchCommand::ForceCancel)
        ));
        for _ in 0..20 {
            if db_cancel_called.load(Ordering::Relaxed) {
                break;
            }
            std::thread::sleep(Duration::from_millis(5));
        }
        assert!(db_cancel_called.load(Ordering::Relaxed));
        assert!(matches!(
            event,
            QueryProgress::LazyFetchClosed {
                index: 3,
                session_id: 42,
                operation_id: 42,
                connection_generation: 7,
                cancelled: true,
                cursor_closed: false,
                fetch_worker_done: false,
                error_kind: InterruptKind::UnsafeOrUnknown,
            }
        ));
    }

