    #[test]
    fn lazy_fetch_execute_retry_waits_without_reissuing_cancel_and_eventually_stops() {
        assert_eq!(
            SqlEditorWidget::lazy_fetch_cancel_before_execution_decision(
                42,
                None,
                0,
                false,
                Duration::from_secs(5),
            ),
            LazyFetchCancelBeforeExecutionDecision::RequestCancelAndRetry {
                next_retry_attempt: 1
            }
        );
        assert_eq!(
            SqlEditorWidget::lazy_fetch_cancel_before_execution_decision(
                42,
                Some(42),
                1,
                true,
                Duration::from_secs(5),
            ),
            LazyFetchCancelBeforeExecutionDecision::WaitForCancelAndRetry {
                next_retry_attempt: 2
            }
        );
        assert_eq!(
            SqlEditorWidget::lazy_fetch_cancel_before_execution_decision(
                42,
                Some(42),
                LAZY_FETCH_CANCEL_RETRY_LIMIT,
                true,
                Duration::from_secs(5),
            ),
            LazyFetchCancelBeforeExecutionDecision::GiveUp
        );
        assert_eq!(
            SqlEditorWidget::lazy_fetch_cancel_before_execution_decision(
                43,
                Some(42),
                7,
                true,
                Duration::from_secs(5),
            ),
            LazyFetchCancelBeforeExecutionDecision::WaitForCancelAndRetry {
                next_retry_attempt: 1
            },
            "a different lazy session should reset the retry budget"
        );
    }

