    #[test]
    fn mysql_lock_wait_timeout_autocommit_off_dml_blocks_next_execution() {
        let sql = "UPDATE accounts SET balance = balance + 1 WHERE id = 1";
        let effects = SqlEditorWidget::mysql_statement_session_effects_for_sql(sql);
        let interruption_requires_transaction_decision =
            crate::db::statement_interruption_requires_transaction_decision(
                crate::db::StatementInterruption {
                    lock_wait_timeout: true,
                    ..crate::db::StatementInterruption::default()
                },
                false,
                TransactionSessionState::Clean,
                effects.state_hint,
            );
        assert!(
            interruption_requires_transaction_decision,
            "autocommit-off DML lock-wait timeout must be resolved before more SQL runs"
        );

        let reuse_decision = crate::db::decide_mysql_pooled_session_after_action(
            crate::db::MySqlPooledActionDecisionContext {
                requires_transaction_decision: true,
                action_released_physical_session: false,
                was_cancelled: false,
                recoverable_timeout: false,
                lock_wait_timeout: true,
                action_result_allows_reuse: false,
                state_hint: effects.state_hint,
            },
        );
        assert_eq!(
            reuse_decision,
            crate::db::MySqlPooledSessionReuseDecision::RetainIfSessionInfoSynced,
            "retain here means retain the physical transaction for commit/rollback, not free reuse"
        );

        let retained = SqlEditorWidget::mysql_retained_session_state_after_statement_from_probe(
            crate::db::DatabaseType::MySQL,
            RetainedSessionState::default(),
            sql,
            effects,
            false,
            true,
            crate::db::TransactionProbeResult {
                may_have_uncommitted_work: false,
                used_fallback: false,
            },
            interruption_requires_transaction_decision,
        );
        assert_eq!(
            retained.transaction_state(),
            TransactionSessionState::DecisionRequired
        );
        assert!(retained.blocks_execution());
    }

