    #[test]
    fn mysql_raw_transaction_mode_change_is_blocked_on_dirty_retained_session() {
        let prior =
            RetainedSessionState::from_transaction_state(TransactionSessionState::MaybeDirty);

        for sql in [
            "SET TRANSACTION ISOLATION LEVEL SERIALIZABLE",
            "SET SESSION TRANSACTION READ ONLY",
            "SET @@session.transaction_isolation = 'SERIALIZABLE'",
        ] {
            let err = SqlEditorWidget::ensure_mysql_statement_transaction_option_change_allowed(
                prior,
                SqlEditorWidget::mysql_statement_session_effects_for_sql(sql),
            )
            .expect_err("dirty retained transaction must block raw transaction mode changes");
            assert!(err.contains("transaction mode"), "{sql}: {err}");
            assert!(err.contains(prior.label()), "{sql}: {err}");
        }
    }

    #[test]
    fn mysql_raw_transaction_mode_change_can_replace_clean_retained_mode_override() {
        let post_processor =
            crate::db::statement_session_post_processor_for(crate::db::DatabaseType::MySQL);

        for prior_sql in [
            "SET TRANSACTION ISOLATION LEVEL SERIALIZABLE",
            "SET SESSION TRANSACTION READ ONLY",
            "SET @@transaction_isolation = 'SERIALIZABLE'",
        ] {
            let prior = crate::db::retained_session_state_after_statement(
                post_processor,
                RetainedSessionState::default(),
                SqlEditorWidget::mysql_statement_session_effects_for_sql(prior_sql),
                false,
                false,
                false,
                false,
            );

            for next_sql in [
                "SET TRANSACTION ISOLATION LEVEL READ COMMITTED",
                "SET SESSION TRANSACTION READ WRITE",
                "SET @@session.transaction_isolation = 'READ-COMMITTED'",
            ] {
                SqlEditorWidget::ensure_mysql_statement_transaction_option_change_allowed(
                    prior,
                    SqlEditorWidget::mysql_statement_session_effects_for_sql(next_sql),
                )
                .unwrap_or_else(|err| {
                    panic!("{next_sql} should be allowed after {prior_sql}: {err}")
                });
            }
        }
    }

