    #[test]
    fn mysql_lock_wait_timeout_after_dirty_batch_retains_decision_session() {
        let mut batch_effects = crate::db::MySqlBatchSessionEffects::default();
        SqlEditorWidget::mysql_batch_session_state_hint_for_sql(
            "UPDATE a SET v = 1 WHERE id = 1",
            false,
            &mut batch_effects,
        );
        let interrupted_effects = SqlEditorWidget::mysql_statement_session_effects_for_sql(
            "UPDATE b SET v = 1 WHERE id = 1",
        );
        SqlEditorWidget::apply_interrupted_mysql_batch_statement_effects(
            "UPDATE b SET v = 1 WHERE id = 1",
            false,
            interrupted_effects,
            &mut batch_effects,
        );

        let retained = batch_effects
            .retained_state_after_interrupted_batch(RetainedSessionState::default(), true, false)
            .expect("dirty lock-wait-timeout batch must keep the physical session for resolution");
        assert!(
            retained.requires_transaction_decision(),
            "prior successful DML must not be silently discarded after lock wait timeout"
        );
        let decision = batch_effects.decision_after_interrupted_batch(
            RetainedSessionState::default(),
            true,
            false,
        );
        assert!(matches!(
            decision.outcome,
            RetainedSessionOutcome::Retain(state) if state.requires_transaction_decision()
        ));
    }

