    fn mysql_test_env(name: &str) -> Option<String> {
        env::var(name).ok().filter(|value| !value.trim().is_empty())
    }

    fn mysql_test_server_version() -> Option<String> {
        let Some(host) = mysql_test_env("SPACE_QUERY_TEST_MYSQL_HOST") else {
            eprintln!("skipping: SPACE_QUERY_TEST_MYSQL_HOST is not set");
            return None;
        };
        let Some(database) = mysql_test_env("SPACE_QUERY_TEST_MYSQL_DATABASE") else {
            eprintln!("skipping: SPACE_QUERY_TEST_MYSQL_DATABASE is not set");
            return None;
        };
        let Some(user) = mysql_test_env("SPACE_QUERY_TEST_MYSQL_USER") else {
            eprintln!("skipping: SPACE_QUERY_TEST_MYSQL_USER is not set");
            return None;
        };
        let Some(password) = mysql_test_env("SPACE_QUERY_TEST_MYSQL_PASSWORD") else {
            eprintln!("skipping: SPACE_QUERY_TEST_MYSQL_PASSWORD is not set");
            return None;
        };
        let port = mysql_test_env("SPACE_QUERY_TEST_MYSQL_PORT")
            .and_then(|value| value.parse::<u16>().ok())
            .unwrap_or(3306);

        let mut connection = DatabaseConnection::new();
        connection
            .set_auto_commit(true)
            .expect("set initial MySQL/MariaDB auto-commit");
        connection
            .connect(ConnectionInfo::new_with_type(
                "MYSQL_TEST",
                &user,
                &password,
                &host,
                port,
                &database,
                DatabaseType::MySQL,
            ))
            .expect("MySQL/MariaDB version probe connection should succeed");
        let conn = connection.get_mysql_connection_mut()?;
        conn.query_first::<String, _>("SELECT VERSION()")
            .expect("MySQL/MariaDB version probe should succeed")
    }

    fn mysql_test_server_is_mariadb() -> Option<bool> {
        mysql_test_server_version().map(|version| version.to_ascii_lowercase().contains("mariadb"))
    }

    fn mysql_test_server_is_mysql8_or_newer() -> Option<bool> {
        let version = mysql_test_server_version()?;
        if version.to_ascii_lowercase().contains("mariadb") {
            return Some(false);
        }
        let major = version
            .split(|ch: char| !ch.is_ascii_digit())
            .find(|part| !part.is_empty())
            .and_then(|part| part.parse::<u32>().ok())
            .unwrap_or(0);
        Some(major >= 8)
    }

    #[test]
    #[ignore = "requires local MySQL or MariaDB test database via SPACE_QUERY_TEST_MYSQL_* env vars"]
    fn mysql_pooled_execution_empty_scope_resets_reused_session_database() {
        let Some(connection) = mysql_test_connection_with_mode(TransactionMode::default()) else {
            return;
        };
        let database = connection.get_info().service_name.clone();
        if database.trim().is_empty() {
            eprintln!("skipping: SPACE_QUERY_TEST_MYSQL_DATABASE must be non-empty");
            return;
        }
        let advanced = connection.get_info().advanced.clone();
        let Some(DbPoolSession::MySQL { mut conn, .. }) = connection
            .acquire_pool_session()
            .expect("acquire MySQL pool session")
        else {
            panic!("expected MySQL pool session");
        };

        conn.as_mut()
            .select_db(database.as_str())
            .expect("select test database before empty-scope reset");
        assert_eq!(
            conn.query_first::<Option<String>, _>("SELECT DATABASE()")
                .expect("read selected database")
                .flatten()
                .as_deref(),
            Some(database.as_str())
        );

        SqlEditorWidget::prepare_mysql_pooled_session_database(&mut conn, "", &advanced, false)
            .expect("empty execution scope should reset stale database state");
        let current_database = conn
            .query_first::<Option<String>, _>("SELECT DATABASE()")
            .expect("read database after empty-scope reset")
            .flatten();
        assert_eq!(current_database, None);
    }

    #[test]
    #[ignore = "requires local MySQL or MariaDB test database via SPACE_QUERY_TEST_MYSQL_* env vars"]
    fn mysql_global_empty_scope_recheck_resets_reused_session_database() {
        let Some(connection) = mysql_test_connection_with_mode(TransactionMode::default()) else {
            return;
        };
        let database = connection.get_info().service_name.clone();
        if database.trim().is_empty() {
            eprintln!("skipping: SPACE_QUERY_TEST_MYSQL_DATABASE must be non-empty");
            return;
        }

        let shared_connection = Arc::new(Mutex::new(connection));
        let (connection_generation, mut conn) = {
            let mut connection = shared_connection
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            let connection_generation = connection.connection_generation();
            let Some(DbPoolSession::MySQL { mut conn, .. }) = connection
                .acquire_pool_session()
                .expect("acquire MySQL pool session")
            else {
                panic!("expected MySQL pool session");
            };
            conn.as_mut()
                .select_db(database.as_str())
                .expect("select test database before empty-scope recheck");
            connection
                .switch_mysql_database("")
                .expect("primary MySQL connection should clear current database");
            (connection_generation, conn)
        };

        assert_eq!(
            conn.query_first::<Option<String>, _>("SELECT DATABASE()")
                .expect("read selected database")
                .flatten()
                .as_deref(),
            Some(database.as_str())
        );

        SqlEditorWidget::apply_mysql_global_database_before_pooled_action(
            &shared_connection,
            &mut conn,
            "mysql empty scope recheck",
            connection_generation,
            true,
            false,
        )
        .expect("empty global scope recheck should reset stale database state");
        let current_database = conn
            .query_first::<Option<String>, _>("SELECT DATABASE()")
            .expect("read database after empty-scope recheck")
            .flatten();
        assert_eq!(current_database, None);
    }

