    #[test]
    #[ignore = "requires local Oracle listener"]
    fn oracle_thin_lazy_fetch_help_join_emits_grid_batches() {
        let sql = "select * from help a join help b on 1=1";
        let progress = oracle_lazy_worker_progress_for_sql(OracleDriverMode::Thin, sql, 25, false);
        let failures = oracle_thin_progress_failures(&progress);
        let snapshot = oracle_grid_snapshot(&progress);

        assert!(
            failures.is_empty(),
            "Oracle Thin lazy failures: {failures:?}"
        );
        assert!(
            progress
                .iter()
                .any(|event| matches!(event, QueryProgress::LazyFetchSession { .. })),
            "Thin should create a lazy fetch session"
        );
        assert!(
            progress
                .iter()
                .any(|event| matches!(event, QueryProgress::LazyFetchWaiting { .. })),
            "Thin should pause after the initial grid batch"
        );
        assert!(
            progress
                .iter()
                .any(|event| matches!(event, QueryProgress::LazyFetchClosed { .. })),
            "Thin should close the lazy cursor after lazy fetch commands"
        );
        let initial_batch_len = progress
            .iter()
            .find_map(|event| match event {
                QueryProgress::Rows { rows, .. } => Some(rows.len()),
                _ => None,
            })
            .unwrap_or_default();
        assert!(
            initial_batch_len <= 25,
            "initial Thin lazy batch should not fetch the full result: {initial_batch_len}"
        );
        assert!(!snapshot.columns.is_empty(), "datagrid should have columns");
        assert!(!snapshot.rows.is_empty(), "datagrid should have rows");
        assert!(
            snapshot.rows.len() > initial_batch_len,
            "FetchMore should append rows after the initial lazy batch"
        );
    }

