    #[test]
    #[ignore = "requires local Oracle listener"]
    fn oracle_thin_protocol_318_fv12_lazy_fetch_all_ui_path_reaches_direct_row_count() {
        if oracle_thin_skip_unless_requested_protocol(
            318,
            "oracle_thin_protocol_318_fv12_lazy_fetch_all_ui_path_reaches_direct_row_count",
        ) {
            return;
        }
        let sql = "select * from help";
        let config = oracle_thin_live_config_with_protocol(318, 12);
        let mut direct =
            tns_thin::OracleThinSession::connect(config.clone()).expect("thin 318/FV12 login");
        assert_oracle_thin_protocol_318_fv12_no_eor(&direct);
        direct
            .set_call_timeout(Some(Duration::from_secs(30)))
            .expect("set direct fetch timeout");
        let direct_rows = direct
            .query_described_fetch_all(sql, 25)
            .expect("direct 318/FV12 HELP fetch all")
            .result
            .rows
            .len();
        assert!(
            direct_rows > 25,
            "test must require FetchAll to continue after the initial lazy batch"
        );

        let progress = oracle_lazy_worker_progress_for_sql_with_config_and_drive(
            OracleDriverMode::Thin,
            sql,
            25,
            OracleLazyFetchDrive::FetchAll,
            Some(config),
        );
        let failures = oracle_thin_progress_failures(&progress);
        let snapshot = oracle_grid_snapshot(&progress);
        let finished_rows = progress.iter().find_map(|event| match event {
            QueryProgress::StatementFinished { result, .. } if result.success => {
                Some(result.row_count)
            }
            _ => None,
        });
        let fetch_all_started = progress
            .iter()
            .any(|event| matches!(event, QueryProgress::LazyFetchWaiting { .. }));

        assert!(
            failures.is_empty(),
            "Oracle Thin 318/FV12 lazy FetchAll failures: {failures:?}"
        );
        assert!(
            fetch_all_started,
            "318/FV12 UI path must enter the lazy waiting state before FetchAll"
        );
        assert_eq!(
            snapshot.rows.len(),
            direct_rows,
            "318/FV12 UI lazy FetchAll should reach the direct fetch-all row count"
        );
        assert_eq!(
            finished_rows,
            Some(direct_rows),
            "318/FV12 FetchAll statement feedback should report the fetched HELP row count"
        );
    }

    #[test]
    #[ignore = "requires local Oracle listener"]
    fn oracle_thin_protocol_318_fv12_fetch_more_then_fetch_all_ui_path_reaches_direct_row_count() {
        if oracle_thin_skip_unless_requested_protocol(
            318,
            "oracle_thin_protocol_318_fv12_fetch_more_then_fetch_all_ui_path_reaches_direct_row_count",
        ) {
            return;
        }
        let sql = "select * from help";
        let config = oracle_thin_live_config_with_protocol(318, 12);
        let mut direct =
            tns_thin::OracleThinSession::connect(config.clone()).expect("thin 318/FV12 login");
        assert_oracle_thin_protocol_318_fv12_no_eor(&direct);
        direct
            .set_call_timeout(Some(Duration::from_secs(30)))
            .expect("set direct fetch timeout");
        let direct_rows = direct
            .query_described_fetch_all(sql, 25)
            .expect("direct 318/FV12 HELP fetch all")
            .result
            .rows
            .len();
        assert!(
            direct_rows > 50,
            "test must require FetchAll to continue after initial fetch and one FetchMore"
        );

        let progress = oracle_lazy_worker_progress_for_sql_with_config_and_drive(
            OracleDriverMode::Thin,
            sql,
            25,
            OracleLazyFetchDrive::SingleFetchMoreThenFetchAll,
            Some(config),
        );
        let failures = oracle_thin_progress_failures(&progress);
        let snapshot = oracle_grid_snapshot(&progress);
        let finished_rows = progress.iter().find_map(|event| match event {
            QueryProgress::StatementFinished { result, .. } if result.success => {
                Some(result.row_count)
            }
            _ => None,
        });
        let waiting_count = progress
            .iter()
            .filter(|event| matches!(event, QueryProgress::LazyFetchWaiting { .. }))
            .count();
        let row_batches = progress
            .iter()
            .filter(|event| matches!(event, QueryProgress::Rows { .. }))
            .count();

        assert!(
            failures.is_empty(),
            "Oracle Thin 318/FV12 FetchMore then FetchAll failures: {failures:?}"
        );
        assert!(
            waiting_count >= 2,
            "318/FV12 UI path must wait once before FetchMore and again before FetchAll; events={}",
            progress.len()
        );
        assert!(
            row_batches >= 3,
            "test must observe initial rows, FetchMore rows, and FetchAll rows; events={}",
            progress.len()
        );
        assert_eq!(
            snapshot.rows.len(),
            direct_rows,
            "318/FV12 FetchMore then FetchAll should reach the direct fetch-all row count"
        );
        assert_eq!(
            finished_rows,
            Some(direct_rows),
            "318/FV12 FetchMore then FetchAll feedback should report the fetched row count"
        );
    }

