    #[test]
    #[ignore = "requires local Oracle listener"]
    fn oracle_thin_lazy_fetch_cleanup_failure_releases_handle_and_same_tab_can_query() {
        let (sender, receiver) = mpsc::channel();
        let session = Arc::new(Mutex::new(SessionState {
            db_type: DatabaseType::Oracle,
            ..SessionState::default()
        }));
        let active_lazy_fetch = Arc::new(Mutex::new(None));
        let pooled_db_session = SharedDbSessionLease::new();
        let pool = tns_thin::OracleThinSessionPool::new(
            oracle_thin_live_config(),
            tns_thin::pool::PoolOptions {
                max_size: 2,
                acquire_timeout: Duration::from_secs(5),
            },
        );
        let sentinel_conn = pool
            .acquire()
            .expect("acquire sentinel Oracle thin session");
        assert!(
            pooled_db_session.apply_retained_session_disposition(
                1,
                1,
                crate::db::DbSessionLease::OracleThin(Box::new(sentinel_conn)),
                crate::db::RetainedSessionDisposition::Retain(
                    crate::db::RetainedSessionState::default(),
                ),
                "oracle thin lazy cleanup failure live test seed",
            ),
            "seed retained session should occupy the tab slot"
        );

        let lazy_conn = pool.acquire().expect("acquire Oracle thin lazy session");
        let session_id = 45;
        SqlEditorWidget::start_oracle_thin_lazy_select(
            lazy_conn,
            pooled_db_session.clone(),
            1,
            1,
            crate::db::RetainedSessionState::default(),
            sender.clone(),
            session,
            "ORACLE_THIN_CLEANUP_FAILURE_TEST".to_string(),
            0,
            "SELECT object_id FROM all_objects WHERE rownum <= 50".to_string(),
            Vec::new(),
            true,
            true,
            " ".to_string(),
            "NULL".to_string(),
            active_lazy_fetch.clone(),
            session_id,
            1,
            None,
        )
        .expect("start Oracle thin lazy select");

        let mut cancel_sent = false;
        let mut events = Vec::new();
        let deadline = Instant::now() + Duration::from_secs(60);
        loop {
            match receiver.recv_timeout(Duration::from_millis(50)) {
                Ok(event) => {
                    if matches!(event, QueryProgress::LazyFetchWaiting { .. }) && !cancel_sent {
                        assert!(SqlEditorWidget::cancel_lazy_fetch_handle_for_session(
                            &active_lazy_fetch,
                            &pooled_db_session,
                            Some(session_id),
                            true,
                        ));
                        cancel_sent = true;
                    }
                    let closed = matches!(event, QueryProgress::LazyFetchClosed { .. });
                    events.push(event);
                    if closed {
                        break;
                    }
                }
                Err(mpsc::RecvTimeoutError::Timeout) if Instant::now() < deadline => {}
                Err(err) => panic!(
                    "Oracle thin lazy cleanup failure test ended before close: {err}; events={}",
                    events.len()
                ),
            }
            if Instant::now() >= deadline {
                panic!(
                    "Oracle thin lazy cleanup failure test timed out; cancel_sent={cancel_sent}; events={}",
                    events.len()
                );
            }
        }

        assert!(
            cancel_sent,
            "lazy fetch should have been cancelled from waiting state"
        );
        assert!(
            active_lazy_fetch
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .is_none(),
            "cleanup failure must clear the active lazy handle"
        );
        assert!(
            events.iter().any(|event| {
                matches!(
                    event,
                    QueryProgress::LazyFetchClosed {
                        cancelled: true,
                        cursor_closed: false,
                        fetch_worker_done: true,
                        error_kind: InterruptKind::UnsafeOrUnknown,
                        ..
                    }
                )
            }),
            "cleanup failure should emit terminal close flags; events={}",
            events.len()
        );

        let retained_session =
            match pooled_db_session.take_reusable_lease(1, 1, crate::db::DatabaseType::Oracle) {
                crate::db::RetainedSessionTakeOutcome::Reusable(session) => session,
                crate::db::RetainedSessionTakeOutcome::NoSession => {
                    panic!(
                        "same tab should still be able to take a retained session, got no session"
                    )
                }
                crate::db::RetainedSessionTakeOutcome::DiscardedBecauseStale => {
                    panic!("same tab retained session was discarded as stale")
                }
                crate::db::RetainedSessionTakeOutcome::BlockedContextMismatch(_) => {
                    panic!("same tab retained session was blocked by context mismatch")
                }
            };
        let (mut conn, _) = retained_session
            .into_oracle_thin_connection_with_retained_state()
            .expect("retained tab session should be Oracle thin");
        let (_columns, rows) =
            SqlEditorWidget::oracle_thin_select_cells(&mut conn, "SELECT 1 AS ok FROM dual")
                .expect("same tab query after lazy cleanup failure");
        assert_eq!(rows, vec![vec!["1".to_string()]]);
    }

    #[test]
    #[ignore = "requires local Oracle listener"]
    fn oracle_thin_cancel_error_discards_session_and_same_tab_can_query() {
        let pool = tns_thin::OracleThinSessionPool::new(
            oracle_thin_live_config(),
            tns_thin::pool::PoolOptions {
                max_size: 1,
                acquire_timeout: Duration::from_secs(5),
            },
        );
        let mut conn = pool.acquire().expect("acquire Oracle thin session");
        let cancel_handle = conn.cancel_handle();
        let cancel_flag = Arc::new(Mutex::new(false));
        let cancel_flag_for_thread = cancel_flag.clone();
        let cancel_thread = std::thread::spawn(move || {
            std::thread::sleep(Duration::from_millis(300));
            store_mutex_bool(&cancel_flag_for_thread, true);
            let result = cancel_handle.break_execution();
            std::thread::sleep(Duration::from_millis(700));
            cancel_handle.force_close();
            result
        });
        let session = Arc::new(Mutex::new(SessionState {
            db_type: DatabaseType::Oracle,
            ..SessionState::default()
        }));
        let current_operation_autocommit = Arc::new(Mutex::new(true));
        let (sender, receiver) = mpsc::channel();
        let outcome = SqlEditorWidget::execute_oracle_thin_batch(
            &mut conn,
            &sender,
            "SELECT COUNT(*) FROM all_objects a, all_objects b, all_objects c",
            "ORACLE_THIN_CANCEL_LIVE_TEST",
            &session,
            &cancel_flag,
            true,
            true,
            RetainedSessionState::default(),
            TransactionMode::default(),
            "oracle thin cancel live test",
            &current_operation_autocommit,
            None,
            None,
        );
        drop(sender);
        let progress = receiver.iter().collect::<Vec<_>>();
        let _ = cancel_thread.join().expect("cancel thread");
        assert!(
            outcome.had_error,
            "cancelled long select should report an error"
        );
        let expected_cancel_message = format!("Error: {}", SqlEditorWidget::cancel_message());
        assert!(
            progress.iter().any(|event| matches!(
                event,
                QueryProgress::StatementFinished { result, .. }
                    if !result.success && result.message == expected_cancel_message
            )),
            "cancelled long select should surface the normalized cancel message"
        );

        let disposition = SqlEditorWidget::oracle_thin_execution_disposition(
            load_mutex_bool(&cancel_flag),
            outcome.had_error,
            conn.is_broken(),
            outcome.retained_state,
            crate::db::session_policy::SqlKind::SelectLike,
            true,
            false,
        );
        assert!(matches!(
            &disposition,
            crate::db::RetainedSessionDisposition::DiscardPhysical
        ));
        let pooled_db_session = SharedDbSessionLease::new();
        pooled_db_session.apply_retained_session_disposition(
            1,
            1,
            crate::db::DbSessionLease::OracleThin(Box::new(conn)),
            disposition,
            "oracle thin cancel live test",
        );
        assert!(
            pooled_db_session.snapshot().is_none(),
            "cancel error should not leave a retained tab session"
        );

        let mut next_conn = pool
            .acquire()
            .expect("same tab should be able to acquire a fresh Oracle thin session");
        let (_columns, rows) =
            SqlEditorWidget::oracle_thin_select_cells(&mut next_conn, "SELECT 1 AS ok FROM dual")
                .expect("same tab query after cancel error");
        assert_eq!(rows, vec![vec!["1".to_string()]]);
    }

