    #[test]
    #[ignore = "requires local Oracle listener and OCI client"]
    fn oracle_oci_and_thin_function_refcursor_bind_rows_match() {
        let _oracle_schema_guard = oracle_thin_shared_schema_test_guard();
        let function_name = format!("OQT_RC_FUNC_{}", std::process::id());
        let create_sql = format!(
            "CREATE OR REPLACE FUNCTION {function_name} RETURN SYS_REFCURSOR IS
               rc SYS_REFCURSOR;
             BEGIN
               OPEN rc FOR SELECT 7 AS n, 'grid' AS txt FROM dual;
               RETURN rc;
             END;"
        );
        let call_sql = format!("BEGIN :v_result := {function_name}(); END;");

        let mut thin_conn =
            tns_thin::OracleThinSession::connect(oracle_thin_live_config()).expect("thin login");
        let _ = SqlEditorWidget::execute_oracle_thin_statement(
            &mut thin_conn,
            format!("DROP FUNCTION {function_name}"),
            false,
        );
        SqlEditorWidget::execute_oracle_thin_statement(&mut thin_conn, create_sql, false)
            .expect("create refcursor return function");

        let thin_session = Arc::new(Mutex::new(SessionState {
            db_type: DatabaseType::Oracle,
            ..SessionState::default()
        }));
        {
            let mut guard = thin_session.lock().expect("thin session lock");
            guard.binds.insert(
                "V_RESULT".to_string(),
                BindVar::new(BindDataType::RefCursor),
            );
        }
        let thin_outcome = SqlEditorWidget::execute_oracle_thin_statement_with_binds_outcome(
            &mut thin_conn,
            &call_sql,
            &thin_session,
            false,
        )
        .expect("thin function refcursor bind");
        let thin_cursor = thin_outcome
            .ref_cursor_results
            .into_iter()
            .next()
            .map(|(_, cursor)| cursor)
            .expect("thin should return refcursor bind");
        let thin_cursor = SqlEditorWidget::oracle_thin_fetch_cursor_result(
            &mut thin_conn,
            thin_cursor,
            &thin_session,
            None,
        )
        .expect("fetch thin function refcursor rows");

        let (host, port, service, username, password) = oracle_live_connection_parts();
        let info = ConnectionInfo::new_with_type(
            "local",
            &username,
            &password,
            &host,
            port,
            &service,
            DatabaseType::Oracle,
        );
        crate::db::DatabaseConnection::test_connection(&info)
            .expect("Oracle client should initialize");
        let conn = oracle::Connection::connect(&username, &password, info.connection_string())
            .expect("connect Oracle OCI");
        let mut oci_state = SessionState {
            db_type: DatabaseType::Oracle,
            ..SessionState::default()
        };
        oci_state.binds.insert(
            "V_RESULT".to_string(),
            BindVar::new(BindDataType::RefCursor),
        );
        let binds = QueryExecutor::resolve_binds(&call_sql, &oci_state).expect("resolve OCI binds");
        let stmt = QueryExecutor::execute_with_binds(&conn, &call_sql, &binds)
            .expect("OCI function refcursor bind");
        let mut ref_cursors =
            QueryExecutor::extract_ref_cursors(&stmt, &binds).expect("OCI refcursor binds");
        let (_cursor_name, mut cursor) =
            ref_cursors.pop().expect("OCI should return refcursor bind");
        let mut oci_columns = Vec::new();
        let mut oci_rows = Vec::new();
        let (_result, cancelled) = QueryExecutor::execute_ref_cursor_streaming(
            &mut cursor,
            "REFCURSOR :V_RESULT",
            &mut |columns| {
                oci_columns = columns.iter().map(|column| column.name.clone()).collect();
            },
            &mut |row| {
                oci_rows.push(row);
                true
            },
        )
        .expect("fetch OCI refcursor rows");

        assert!(!cancelled);
        assert_eq!(thin_cursor.columns, oci_columns);
        assert_eq!(thin_cursor.rows, oci_rows);
        assert_eq!(
            thin_cursor.rows,
            vec![vec!["7".to_string(), "grid".to_string()]]
        );

        let _ = SqlEditorWidget::execute_oracle_thin_statement(
            &mut thin_conn,
            format!("DROP FUNCTION {function_name}"),
            false,
        );
    }

