    #[test]
    #[ignore = "requires local Oracle listener"]
    fn oracle_thin_batch_cursor_results_emit_like_oci_after_plsql_success() {
        let supports_implicit = oracle_thin_live_supports_implicit_resultsets();
        let sql = if supports_implicit {
            "VAR v_rc REFCURSOR\n\
             BEGIN OPEN :v_rc FOR SELECT 3 AS n, 'ref' AS txt FROM dual; END;\n\
             /\n\
             DECLARE\n\
               rc SYS_REFCURSOR;\n\
             BEGIN\n\
               OPEN rc FOR SELECT 4 AS n, 'implicit' AS txt FROM dual;\n\
               DBMS_SQL.RETURN_RESULT(rc);\n\
             END;\n\
             /\n"
        } else {
            "VAR v_rc REFCURSOR\n\
             BEGIN OPEN :v_rc FOR SELECT 3 AS n, 'ref' AS txt FROM dual; END;\n\
             /\n"
        };
        let progress = oracle_thin_run_script(sql);
        let failures = oracle_thin_progress_failures(&progress);
        assert!(failures.is_empty(), "failures: {failures:?}");

        let assert_cursor_grid_sequence = |label: &str| {
            let finished_pos = progress
                .iter()
                .position(|event| {
                    matches!(
                        event,
                        QueryProgress::StatementFinished { result, .. }
                            if result.success && result.is_select && result.sql.trim() == label
                    )
                })
                .unwrap_or_else(|| panic!("{label} select result should finish"));
            let index = match &progress[finished_pos] {
                QueryProgress::StatementFinished { index, .. } => *index,
                _ => unreachable!(),
            };
            let started_pos = progress
                .iter()
                .position(|event| matches!(event, QueryProgress::StatementStart { index: row_index } if *row_index == index))
                .unwrap_or_else(|| panic!("{label} should start a result statement"));
            let select_pos = progress
                .iter()
                .position(|event| matches!(event, QueryProgress::SelectStart { index: row_index, .. } if *row_index == index))
                .unwrap_or_else(|| panic!("{label} should open a grid before rows"));
            let rows_pos = progress
                .iter()
                .position(|event| matches!(event, QueryProgress::Rows { index: row_index, .. } if *row_index == index))
                .unwrap_or_else(|| panic!("{label} should stream rows"));
            assert!(
                started_pos < select_pos && select_pos < rows_pos && rows_pos < finished_pos,
                "{label} should follow OCI cursor grid progress order"
            );
        };
        assert_cursor_grid_sequence("REFCURSOR :V_RC");
        if supports_implicit {
            assert_cursor_grid_sequence("IMPLICIT RESULT 1");
        }

        let rows_for_sql = |label: &str| {
            let index = progress
                .iter()
                .find_map(|event| match event {
                    QueryProgress::StatementFinished { index, result, .. }
                        if result.success && result.is_select && result.sql.trim() == label =>
                    {
                        Some(*index)
                    }
                    _ => None,
                })
                .unwrap_or_else(|| panic!("{label} select result should be emitted"));
            progress
                .iter()
                .filter_map(|event| match event {
                    QueryProgress::Rows {
                        index: row_index,
                        rows,
                    } if *row_index == index => Some(rows.clone()),
                    _ => None,
                })
                .flatten()
                .collect::<Vec<_>>()
        };

        assert_eq!(
            rows_for_sql("REFCURSOR :V_RC"),
            vec![vec!["3".to_string(), "ref".to_string()]]
        );
        if supports_implicit {
            assert_eq!(
                rows_for_sql("IMPLICIT RESULT 1"),
                vec![vec!["4".to_string(), "implicit".to_string()]]
            );
        }
    }

    #[test]
    #[ignore = "requires local Oracle listener"]
    fn oracle_thin_batch_prints_refcursor_with_mixed_scalar_columns() {
        let procedure_name = format!("OQT_UI_RC_MIXED_{}", std::process::id());
        let sql = format!(
            "CREATE OR REPLACE PROCEDURE {procedure_name}(p_rc OUT SYS_REFCURSOR) IS
             BEGIN
               OPEN p_rc FOR
                 SELECT TO_CHAR(DATE '2024-01-02', 'YYYY-MM-DD') AS c_text_func,
                        CAST('plain varchar' AS VARCHAR2(30)) AS c_varchar,
                        CAST(42 AS NUMBER) AS c_number,
                        TIMESTAMP '2024-01-02 03:04:05.123456' AS c_timestamp,
                        DATE '2024-01-03' AS c_date
                 FROM dual;
             END;
             /
             VAR v_rc REFCURSOR
             BEGIN
               {procedure_name}(:v_rc);
             END;
             /
             PRINT v_rc
             DROP PROCEDURE {procedure_name}
             /
             "
        );
        let progress = oracle_thin_run_script(&sql);
        let failures = oracle_thin_progress_failures(&progress);
        assert!(failures.is_empty(), "failures: {failures:?}");

        let index = progress
            .iter()
            .find_map(|event| match event {
                QueryProgress::StatementFinished { index, result, .. }
                    if result.success
                        && result.is_select
                        && result.sql.trim() == "REFCURSOR :V_RC" =>
                {
                    Some(*index)
                }
                _ => None,
            })
            .expect("PRINT v_rc should emit refcursor grid");
        let mut columns = Vec::new();
        let mut rows = Vec::new();
        for event in &progress {
            match event {
                QueryProgress::SelectStart {
                    index: row_index,
                    columns: event_columns,
                    ..
                } if *row_index == index => columns = event_columns.clone(),
                QueryProgress::Rows {
                    index: row_index,
                    rows: event_rows,
                } if *row_index == index => rows.extend(event_rows.clone()),
                _ => {}
            }
        }

        assert_eq!(
            columns,
            vec![
                "C_TEXT_FUNC".to_string(),
                "C_VARCHAR".to_string(),
                "C_NUMBER".to_string(),
                "C_TIMESTAMP".to_string(),
                "C_DATE".to_string(),
            ]
        );
        assert_eq!(
            rows,
            vec![vec![
                "2024-01-02".to_string(),
                "plain varchar".to_string(),
                "42".to_string(),
                "2024-01-02 03:04:05.123456".to_string(),
                "2024-01-03 00:00:00".to_string(),
            ]]
        );
    }

