    #[test]
    #[ignore = "requires local Oracle listener"]
    fn oracle_thin_query_tool_runtime_updates_scalar_inout_binds() {
        let mut conn =
            tns_thin::OracleThinSession::connect(oracle_thin_live_config()).expect("thin login");
        let session = Arc::new(Mutex::new(SessionState::default()));
        {
            let mut guard = session.lock().expect("session lock");
            let mut number = BindVar::new(BindDataType::Number);
            number.value = BindValue::Scalar(Some("10".to_string()));
            guard.binds.insert("V_NUM".to_string(), number);
            guard.binds.insert(
                "V_TXT".to_string(),
                BindVar::new(BindDataType::Varchar2(100)),
            );
        }

        let messages = SqlEditorWidget::execute_oracle_thin_statement_with_binds(
            &mut conn,
            "DECLARE
               PROCEDURE p(p_num IN OUT NUMBER, p_txt OUT VARCHAR2) IS
               BEGIN
                 p_num := p_num + 5;
                 p_txt := 'txt-' || p_num;
               END;
             BEGIN
               p(:v_num, :v_txt);
             END;",
            &session,
            false,
        )
        .expect("execute plsql with scalar binds");

        assert!(messages.iter().any(|line| line == ":V_NUM = 15"));
        assert!(messages.iter().any(|line| line == ":V_TXT = txt-15"));
        let guard = session.lock().expect("session lock");
        assert!(matches!(
            guard.binds.get("V_NUM").map(|bind| &bind.value),
            Some(BindValue::Scalar(Some(value))) if value == "15"
        ));
        assert!(matches!(
            guard.binds.get("V_TXT").map(|bind| &bind.value),
            Some(BindValue::Scalar(Some(value))) if value == "txt-15"
        ));
    }

